import sys, random
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import t4
import planner
from planner import *

seed=29
rnd=random.Random(seed)
n,links,caps,parts,rdem0=t4.gen(rnd)
period=rnd.choice([1,3,1000])
envelope={i:min(c,10**12) for i,c in enumerate(caps) if c>0}
cpl=[period*envelope.get(i,0) for i in range(len(links))]
cap={}
for lid,(u,v) in enumerate(links):
    if cpl[lid]>0:
        cap[(u,v)]=cap.get((u,v),0)+cpl[lid]; cap[(v,u)]=cap.get((v,u),0)+cpl[lid]
k=t4.max_multiplier(n,cap,parts,rdem0)
rdem={v:rdem0[v]*k for v in parts}
total=sum(rdem.values())
orig=dict(cap)
pr=PathReserver(n,dict(cap),sorted(parts),rdem,total)
initcap=dict(pr.cap)
for it in range(20):
    S=deficient_cut(n,pr.m,sorted(parts),rdem,total)
    if S is None: print('feasible now'); break
    S=[v for v in S if v in set(parts)]
    d=pr.cut_deficiency(S)
    got=pr.push(S,d)
    if got<=0:
        print('stuck iter',it); break
    # consistency: usage from pool vs cap decrease
    use={}
    for key,lst in pr.pool.items():
        for walk,c in lst:
            for a in walk:
                use[a]=use.get(a,0)+c
    bad=0
    for a in orig:
        dec=initcap.get(a,0)-pr.cap.get(a,0)
        if a in set(k2 for k2 in pr.pool for w,c in pr.pool[k2] for w2 in [None]):
            pass
    # compare decreases for non compute-compute arcs
    for a in orig:
        u,v=a
        if u in set(parts) and v in set(parts): continue
        dec=initcap.get(a,0)-pr.cap.get(a,0)
        u2=use.get(a,0)
        if dec!=u2: bad+=1; print('  arc',a,'decreased',dec,'used by pool',u2)
    print('iter',it,'pushed',got,'inconsistent arcs',bad)
" 2>&1 | tail -30
